request:
{
 "project": "OUTBREAK MANAGEMENT FUNCTIONAL REQUIREMENTS",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [],
 "turns": [
  {
   "id": "M1:T1",
   "speaker": "Analyst",
   "act": "open",
   "guide": "Analyst opens the meeting about OUTBREAK MANAGEMENT FUNCTIONAL REQUIREMENTS (meeting 1 of 1, kickoff)."
  },
  {
   "id": "M1:T2",
   "speaker": "Client",
   "act": "context",
   "guide": "Client gives the project background below, in their own words.",
   "content": [
    {
     "text": "Outbreak Management (OM) is the PHIN functional area intended to support the needs of investigation, monitoring, management, analysis, and reporting of a health event or act of bioterrorism. Central to the functionality of a system supporting OM is the ability to collect data related to cases and exposures and to create traceable links between all appropriate entities. By tracing the mechanism of transmission and identifying the source of the health event, the appropriate response staff can more effectively contain the event.",
     "role": "background"
    }
   ]
  },
  {
   "id": "M1:T3",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'outbreak management functional requirements' and asks about it."
  },
  {
   "id": "M1:T4",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Analysis, Visualization, and Report Generation: Systems supporting OM should enable investigators to produce both aggregated and individual reports about affected entities and events.",
     "role": "statement"
    },
    {
     "text": "System Integration and Data Exchange: OM information must be exchangeable, based on established standards, between systems involved in the investigation, identification, confirmation, and reporting of a health event.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T5",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T6",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "System Security and Availability: Security of OM data includes the protection of data from corruption and access by unauthorized individuals, as well as the protection of the actual systems supporting OM from sabotage or other failure. A plan must be established for continuing activities when systems supporting OM are unavailable.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T7",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T8",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'system architecture' and asks about it."
  },
  {
   "id": "M1:T9",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must support structured data entry for common forms and fields to ensure data integrity, validity, and standardization.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T10",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM should provide the ability for computers in disconnected mode to reconnect to a server to share OM data among other computers that operate in disconnected mode.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T11",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "OM data should be synchronized so that all instances of OM applications working from the same server are able to share and use the same data.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T12",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T13",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM should be able to electronically record and store data from remote devices that may be uploaded to an aggregating system.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T14",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T15",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM should be capable of using configurable, domain-specific vocabulary.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T16",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'entity data' and asks about it."
  },
  {
   "id": "M1:T17",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must have the capability to capture demographic data about persons involved in an OM investigation, including: Subject ID, name, address, date of birth, gender, phone number, race, ethnicity, and country of citizenship.",
     "role": "statement"
    },
    {
     "text": "Systems supporting OM must have the capability to capture data about organizations (e.g., a local health department, a university, a professional association) involved in an OM investigation, including: organization name, location, and contact information.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T18",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "Systems supporting OM must have the capability to capture data about organizations (e.g., a local health department, a university, a professional association) involved in an OM investigation, including: organization name, location, and contact information.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T19",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T20",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Systems supporting OM must have the capability to capture data about any animals involved in an OM investigation, including: type (dog, monkey, etc), age, gender, owner's name and address, color, weight, and species.",
     "role": "statement"
    }
   ]
  }
 ]
}
